from __future__ import annotations

from exo import *
from exo.libs.memories import DRAM
from exo.API_scheduling import *


# Base LU + solve kernel, written in a locality-friendly form.
@proc
def kernel_ludcmp_base(
    n: size,
    A: DATA_TYPE[n, n] @ DRAM,
    b: DATA_TYPE[n] @ DRAM,
    x: DATA_TYPE[n] @ DRAM,
    y: DATA_TYPE[n] @ DRAM,
):
    w: DATA_TYPE

    # LU decomposition (Doolittle, in-place in A)
    for i in seq(0, n):

        # Compute L entries (strictly below the diagonal).
        # This is the standard forward substitution for the ith row of L.
        for j in seq(0, i):
            w = A[i, j]
            for k in seq(0, j):
                w = w - A[i, k] * A[k, j]
            A[i, j] = w / A[j, j]

        # Compute U entries (diagonal and above) for row i.
        #
        # Original PolyBench code:
        #
        #   for (j = i; j < n; j++) {
        #     w = A[i][j];
        #     for (k = 0; k < i; k++)
        #       w -= A[i][k] * A[k][j];
        #     A[i][j] = w;
        #   }
        #
        # This can be rewritten to an outer-product style update:
        #
        #   for (k = 0; k < i; k++) {
        #     double aik = A[i][k];
        #     for (j = i; j < n; j++)
        #       A[i][j] -= aik * A[k][j];
        #   }
        #
        # For each fixed (i, j), the sequence of subtractions over k is
        # identical in both algorithms; only the order in which we visit
        # different j values changes. Therefore the computed values in A
        # are bitwise identical, but the outer-product form has much better
        # spatial locality for A[k, j] (streaming along rows of A instead of
        # down columns).
        for k in seq(0, i):
            w = A[i, k]          # reuse A[i, k] across the inner j-loop
            for j in seq(i, n):
                A[i, j] = A[i, j] - w * A[k, j]

    # Forward substitution: solve L * y = b.
    for i in seq(0, n):
        w = b[i]
        for j in seq(0, i):
            w = w - A[i, j] * y[j]
        y[i] = w

    # Backward substitution: solve U * x = y.
    #
    # Original C code:
    #   for (i = n-1; i >= 0; i--) {
    #     w = y[i];
    #     for (j = i+1; j < n; j++)
    #       w -= A[i][j] * x[j];
    #     x[i] = w / A[i][i];
    #   }
    #
    # Exo loops are forward-only, so we re-index i as i0 = n-1-i.
    for i in seq(0, n):
        # Corresponds to original index i0 = n - 1 - i
        w = y[n - 1 - i]
        for j in seq(n - i, n):
            w = w - A[n - 1 - i, j] * x[j]
        x[n - 1 - i] = w / A[n - 1 - i, n - 1 - i]


# --------------------------------------------------------------------
# Scheduling / optimization
# --------------------------------------------------------------------
# We now specialize and optimize the base kernel using Exo primitives.
# The primary transformation targets the U-update j-loop:
#   * Canonicalize it to start at 0 so we can safely apply divide_loop.
#   * Tile that j-loop to expose long, contiguous inner loops, which
#     improves cache behavior and helps the C compiler vectorize.

kernel_ludcmp_scheduled = kernel_ludcmp_base

# 1) Locate the j-loop that updates U (it is the second j-loop in the proc).
j_u = kernel_ludcmp_scheduled.find_loop("j #1")

# 2) Shift that j-loop so that it iterates from 0 to (n - i).
#    This simplifies the bounds and makes it amenable to tiling.
kernel_ludcmp_scheduled = shift_loop(kernel_ludcmp_scheduled, j_u, "0")

# 3) Re-locate the (now shifted) U-update j-loop and tile it by 32.
#    This creates an outer loop over tiles (jo) and an inner loop (ji)
#    over up to 32 contiguous columns. The "guard" tail policy ensures
#    correctness for sizes n that are not multiples of 32.
j_u = kernel_ludcmp_scheduled.find_loop("j #1")
kernel_ludcmp_scheduled = divide_loop(
    kernel_ludcmp_scheduled,
    j_u,
    32,
    ("jo", "ji"),
    tail="guard",
)

# 4) Simplify index arithmetic introduced by the previous rewrites.
kernel_ludcmp_scheduled = simplify(kernel_ludcmp_scheduled)

# 5) Export the optimized kernel under the original C-visible name.
kernel_ludcmp = rename(kernel_ludcmp_scheduled, "kernel_ludcmp")
EXO END
*/


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int n = N;

  /* Variable declaration/allocation. */
  POLYBENCH_2D_ARRAY_DECL(A, DATA_TYPE, N, N, n, n);
  POLYBENCH_1D_ARRAY_DECL(b, DATA_TYPE, N, n);
  POLYBENCH_1D_ARRAY_DECL(x, DATA_TYPE, N, n);
  POLYBENCH_1D_ARRAY_DECL(y, DATA_TYPE, N, n);


  /* Initialize array(s). */
  init_array (n,
	      POLYBENCH_ARRAY(A),
	      POLYBENCH_ARRAY(b),
	      POLYBENCH_ARRAY(x),
	      POLYBENCH_ARRAY(y));

  /* Start timer. */
  polybench_start_instruments;

  /* Run Exo kernel. Flatten views to raw pointers. */
  kernel_ludcmp(/*ctxt=*/NULL, n,
                (DATA_TYPE*)POLYBENCH_ARRAY(A),
                (DATA_TYPE*)POLYBENCH_ARRAY(b),
                (DATA_TYPE*)POLYBENCH_ARRAY(x),
                (DATA_TYPE*)POLYBENCH_ARRAY(y));

  /* Stop and print timer. */
  polybench_stop_instruments;
  polybench_print_instruments;

  /* Prevent dead-code elimination. All live-out data must be printed
     by the function call in argument. */
  polybench_prevent_dce(print_array(n, POLYBENCH_ARRAY(x)));

  /* Be clean. */
  POLYBENCH_FREE_ARRAY(A);
  POLYBENCH_FREE_ARRAY(b);
  POLYBENCH_FREE_ARRAY(x);
  POLYBENCH_FREE_ARRAY(y);

  return 0;
