from __future__ import annotations

from exo import *
from exo.API_scheduling import *
from exo.libs.memories import DRAM


# Base LU decomposition + forward/back substitution kernel.
@proc
def kernel_ludcmp(
    n: size,
    A: DATA_TYPE[n, n] @ DRAM,
    b: DATA_TYPE[n] @ DRAM,
    x: DATA_TYPE[n] @ DRAM,
    y: DATA_TYPE[n] @ DRAM,
):
    w: DATA_TYPE

    # LU decomposition: A is overwritten in-place with L (strictly lower
    # triangle) and U (upper triangle, including the diagonal).
    for i in seq(0, n):

        # Compute L entries below the diagonal for row i:
        #   A[i, j] = (A[i, j] - sum_{k < j} A[i, k] * A[k, j]) / A[j, j]
        for j in seq(0, i):
            w = A[i, j]
            for k in seq(0, j):
                w = w - A[i, k] * A[k, j]
            A[i, j] = w / A[j, j]

        # Compute U entries on and above the diagonal for row i using
        # in-place rank-1 updates:
        #
        #   For each k < i, update the trailing part of row i:
        #     A[i, j] -= A[i, k] * A[k, j]  for all j >= i
        #
        # Organizing the computation this way streams across rows of A for
        # both A[i, *] and A[k, *], improving cache locality compared to
        # the classic column-oriented formulation.
        for k in seq(0, i):
            w = A[i, k]
            for jj in seq(0, n - i):
                A[i, i + jj] = A[i, i + jj] - w * A[k, i + jj]

    # Forward substitution to solve L * y = b.
    # L has an implicit unit diagonal and is stored in the strict lower
    # triangle of A.
    for i in seq(0, n):
        w = b[i]
        for j in seq(0, i):
            w = w - A[i, j] * y[j]
        y[i] = w

