    # U is stored in the upper triangle of A, including the diagonal.
    #
    # Original C loop:
    #   for (i0 = n-1; i0 >= 0; i0--) {
    #     w = y[i0];
    #     for (j0 = i0+1; j0 < n; j0++)
    #       w -= A[i0][j0] * x[j0];
    #     x[i0] = w / A[i0][i0];
    #   }
    #
    # Here we express the same computation using forward-running indices.
    for i in seq(0, n):
        # Corresponds to original index i0 = n - 1 - i.
        w = y[n - 1 - i]
