from __future__ import annotations

from exo import *
from exo.libs.memories import DRAM
from exo.API_scheduling import *


@proc
def ludcmp_base(
    n: size,
    A: DATA_TYPE[n, n] @ DRAM,
    b: DATA_TYPE[n] @ DRAM,
    x: DATA_TYPE[n] @ DRAM,
    y: DATA_TYPE[n] @ DRAM,
):
    w: DATA_TYPE

    # ------------------------------------------------------------------
    # In-place LU decomposition of A without pivoting.
    #
    # A is overwritten with L (unit diagonal, stored below the diagonal)
    # and U (stored on and above the diagonal).
    #
    # The L-update (first inner nest) matches the standard Doolittle
    # algorithm.  The U-update is written in an outer-product style:
    # for a fixed row i and multiplier A[i,k], we update the whole
    # trailing row segment A[i, i:n] at once.  This improves cache
    # locality because:
    #   - A[i,k] is loaded once and reused across the j loop
    #   - A[k, i:n] is accessed as a contiguous row
    # instead of the original column-wise access A[k,j].
    # ------------------------------------------------------------------
    for i in seq(0, n):
        # Compute L(i, 0..i-1): strictly lower triangular part of A.
        for j in seq(0, i):
            w = A[i, j]
            for k in seq(0, j):
                w = w - A[i, k] * A[k, j]
            A[i, j] = w / A[j, j]

        # Compute U(i, i..n-1) using an outer-product update
        #   A[i, j] -= A[i, k] * A[k, j]   for k = 0..i-1, j = i..n-1
        # realized as:
        #   for k:  aik = A[i,k]
        #     for jj: j = i + jj
        #       A[i, j] -= aik * A[k, j]
        for k in seq(0, i):
            aik = A[i, k]
            # Length of the active row segment is (n - i).
            for jj in seq(0, n - i):
                A[i, i + jj] = A[i, i + jj] - aik * A[k, i + jj]

    # ------------------------------------------------------------------
    # Forward substitution: solve L * y = b
    # L has unit diagonal, so no division is needed.
    # ------------------------------------------------------------------
    for i in seq(0, n):
        w = b[i]
        for j in seq(0, i):
            w = w - A[i, j] * y[j]
        y[i] = w

    # ------------------------------------------------------------------
    # Backward substitution: solve U * x = y
    #
    # Original C loop (for reference):
    #   for (i = n-1; i >= 0; i--) {
    #     w = y[i];
    #     for (j = i+1; j < n; j++)
    #       w -= A[i][j] * x[j];
    #     x[i] = w / A[i][i];
    #   }
    #
    # We implement the same traversal using a forward loop over i and
    # mapping it to a decreasing physical index (n-1-i).  This keeps
    # Exo happy (no negative-step loops) while preserving the order of
    # operations.
    # ------------------------------------------------------------------
    for i in seq(0, n):
        # Physical row index counting from the bottom.
        # idx = n - 1 - i
        w = y[n - 1 - i]
        for j in seq(n - i, n):
            w = w - A[n - 1 - i, j] * x[j]
        x[n - 1 - i] = w / A[n - 1 - i, n - 1 - i]


