# We now apply Exo scheduling primitives to improve locality and
# vectorization behavior of the U-update.
#
# The "jj" loop in ludcmp_base iterates over the contiguous segment
# A[i, i:n].  We tile this loop so that the innermost loop operates
# on a small fixed-size chunk, which:
#   - keeps a short contiguous segment of A[i, *] hot in cache
#   - is more amenable to auto-vectorization by the C compiler
# The transformation is semantics-preserving and keeps the original
# iteration order of (i, k, jj), only introducing a blocked traversal
# of jj.

tile_j = 32  # tile size along the row dimension of U

kernel_ludcmp = ludcmp_base

# Tile the "jj" loop inside the U-update:
kernel_ludcmp = divide_loop(
    kernel_ludcmp,
    "jj",                    # loop variable name to divide
    tile_j,                  # tile size
    ("jj_outer", "jj_inner"),
    tail="guard",            # handle remainders safely
)

# Simplify index arithmetic after tiling.
kernel_ludcmp = simplify(kernel_ludcmp)

# Expose the scheduled kernel under the name expected by the C driver.
kernel_ludcmp = rename(kernel_ludcmp, "kernel_ludcmp")
